import React, { useState, useEffect } from 'react';
import Card from '../components/Card';

// Imports de dados
import deepData from '../data/deep-end.json';
import unfilteredData from '../data/unfiltered.json';
import labData from '../data/lab.json';

const Game = ({ modeId, onBack }) => {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [questions, setQuestions] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAnimating, setIsAnimating] = useState(false);

  // Mapeamento de Configurações de Design por Modo
  const modeConfigs = {
    deep: { 
      data: deepData, 
      color: '#00F0FF', 
      bg: 'bg-raw-onyx',
      glow: 'shadow-[0_0_20px_rgba(0,240,255,0.4)]'
    },
    unfiltered: { 
      data: unfilteredData, 
      color: '#FF3E3E', 
      bg: 'bg-[#0F0A0A]',
      glow: 'shadow-[0_0_20px_rgba(255,62,62,0.4)]'
    },
    lab: { 
      data: labData, 
      color: '#F2F2F2', 
      bg: 'bg-black',
      glow: 'shadow-[0_0_20px_rgba(242,242,242,0.4)]'
    }
  };

  const config = modeConfigs[modeId] || modeConfigs.deep;

  // Função para iniciar uma categoria específica
  const startCategory = (category) => {
    const preparedQuestions = category.questions.map(q => ({
      text: q,
      category: category.title,
      color: config.color
    }));
    
    setQuestions(preparedQuestions.sort(() => Math.random() - 0.5));
    setSelectedCategory(category);
    setCurrentIndex(0);
  };

  const nextQuestion = () => {
    if (isAnimating || questions.length === 0) return;
    setIsAnimating(true);
    setTimeout(() => {
      setCurrentIndex((prev) => (prev + 1) % questions.length);
      setIsAnimating(false);
    }, 300);
  };

  // --- ESTADO 1: SELEÇÃO DE CATEGORIA ---
  if (!selectedCategory) {
    return (
      <div className={`min-h-screen ${config.bg} flex flex-col items-center justify-center p-6 animate-in fade-in duration-700`}>
        <button 
          onClick={onBack} 
          className="fixed top-8 left-8 text-raw-bone/30 hover:text-white uppercase tracking-[0.3em] text-[10px] font-bold transition-colors"
        >
          ← Main Menu
        </button>
        
        <div className="text-center mb-12">
          <h2 className="text-raw-bone/10 font-archivo text-6xl md:text-8xl uppercase tracking-tighter leading-none mb-2">
            Select
          </h2>
          <h2 style={{ color: config.color }} className="font-archivo text-6xl md:text-8xl uppercase tracking-tighter leading-none">
            Deck
          </h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full max-w-2xl">
          {config.data.categories.map((cat) => (
            <button
              key={cat.id}
              onClick={() => startCategory(cat)}
              className="p-8 border border-raw-bone/5 bg-white/[0.02] hover:bg-white/[0.05] transition-all group text-left relative overflow-hidden"
            >
              <div 
                className="absolute left-0 top-0 h-full w-1 transition-all duration-300 opacity-0 group-hover:opacity-100"
                style={{ backgroundColor: config.color }}
              />
              <h3 className="text-raw-bone font-archivo text-2xl uppercase mb-1">{cat.title}</h3>
              <p className="text-raw-bone/40 text-[10px] uppercase tracking-widest">{cat.description}</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // --- ESTADO 2: O JOGO ATIVO ---
  return (
    <div className={`min-h-screen ${config.bg} flex flex-col items-center justify-center p-6 overflow-hidden transition-colors duration-500`}>
      
      {/* Botão para voltar à seleção de Decks */}
      <button 
        onClick={() => setSelectedCategory(null)}
        className="fixed top-8 left-8 p-4 bg-raw-bone rounded-full hover:scale-110 transition-transform z-50 shadow-2xl"
      >
        <span className="font-bold text-xl block leading-none" style={{ color: config.color }}>✕</span>
      </button>

      {/* HUD de Progresso */}
      <div className="fixed top-20 w-full max-w-md px-10 z-30 md:top-12">
        <div className="h-[2px] bg-raw-bone/10 w-full overflow-hidden">
          <div 
            className={`h-full transition-all duration-500 ${config.glow}`}
            style={{ 
              width: `${((currentIndex + 1) / questions.length) * 100}%`,
              backgroundColor: config.color
            }}
          />
        </div>
        <div className="flex justify-between mt-3 px-1">
          <span className="text-[9px] text-raw-bone/40 uppercase tracking-widest font-bold">
            {selectedCategory.title}
          </span>
          <span className="text-[9px] text-raw-bone/40 uppercase tracking-widest">
            {currentIndex + 1} / {questions.length}
          </span>
        </div>
      </div>

      {/* Área do Cartão */}
      <div 
        onClick={nextQuestion}
        className={`cursor-pointer transition-all duration-300 transform ${
          isAnimating ? 'scale-90 opacity-0 -rotate-3' : 'scale-100 opacity-100 rotate-0'
        } z-20`}
      >
        <Card 
          text={questions[currentIndex].text} 
          category={questions[currentIndex].category}
          color={config.color}
        />
      </div>

      {/* Rodapé do Jogo */}
      <div className="mt-16 flex flex-col items-center">
        <button 
          onClick={nextQuestion}
          className="text-raw-bone font-archivo text-[10px] uppercase tracking-[0.6em] opacity-30 hover:opacity-100 transition-opacity"
        >
          Click to proceed
        </button>
      </div>
    </div>
  );
};

export default Game;
